#!/bin/bash\n\n# Frontend Signature JSON-Only Validation Script\n# This script MUST FAIL if legacy signature rendering is found\n\nset -e\n\necho \"🔍 Validating frontend signature rendering is JSON-only...\"\n\n# Check for forbidden legacy signature rendering patterns\nFORBIDDEN_PATTERNS=(\n    \"resolveSignatureSrc\"\n    \"signature_data\"\n    \"signature_image_url\"\n    \"signature_render_mode\"\n    \"card_image\"\n    \"template_url\"\n    \"<img.*signature\"\n    \"Image.*signature\"\n)\n\n# Directories to check\nCHECK_DIRS=(\n    \"app/frontend/src/features/ptw\"\n    \"app/frontend/src/components\"\n)\n\nERRORS_FOUND=0\n\nfor dir in \"${CHECK_DIRS[@]}\"; do\n    if [ -d \"$dir\" ]; then\n        echo \"📁 Checking directory: $dir\"\n        \n        for pattern in \"${FORBIDDEN_PATTERNS[@]}\"; do\n            echo \"  🔎 Searching for pattern: $pattern\"\n            \n            # Search for pattern in TypeScript/JavaScript files\n            if grep -r -n --include=\"*.tsx\" --include=\"*.ts\" --include=\"*.jsx\" --include=\"*.js\" \"$pattern\" \"$dir\" 2>/dev/null; then\n                echo \"❌ CRITICAL: Found forbidden pattern '$pattern' in $dir\"\n                echo \"   This violates the JSON-only signature contract!\"\n                ERRORS_FOUND=$((ERRORS_FOUND + 1))\n            fi\n        done\n    else\n        echo \"⚠️  Directory $dir not found, skipping...\"\n    fi\ndone\n\n# Check for required JSON-only patterns\nREQUIRED_PATTERNS=(\n    \"signature_payload\"\n    \"payload_version\"\n    \"strokes\"\n)\n\necho \"\\n✅ Checking for required JSON-only patterns...\"\n\nfor dir in \"${CHECK_DIRS[@]}\"; do\n    if [ -d \"$dir\" ]; then\n        for pattern in \"${REQUIRED_PATTERNS[@]}\"; do\n            if ! grep -r -q --include=\"*.tsx\" --include=\"*.ts\" \"$pattern\" \"$dir\" 2>/dev/null; then\n                echo \"⚠️  Warning: Required pattern '$pattern' not found in $dir\"\n                echo \"   This might indicate incomplete JSON-only implementation\"\n            else\n                echo \"✅ Found required pattern: $pattern\"\n            fi\n        done\n    fi\ndone\n\n# Final result\nif [ $ERRORS_FOUND -gt 0 ]; then\n    echo \"\\n❌ VALIDATION FAILED: Found $ERRORS_FOUND forbidden legacy signature patterns\"\n    echo \"   Frontend signature rendering MUST be JSON-only!\"\n    echo \"   Remove all legacy image-based signature rendering.\"\n    exit 1\nelse\n    echo \"\\n✅ VALIDATION PASSED: No forbidden legacy signature patterns found\"\n    echo \"   Frontend signature rendering appears to be JSON-only compliant\"\n    exit 0\nfi\n